  },
  defaultVariants: { direction: 'column', wrap: false },
});

export const centerVariants = tv({
  base: 'flex items-center justify-center',
  variants: {
    inline: { true: 'inline-flex' },
  },
});

export type StackVariantProps = VariantProps<typeof stackVariants>;

